export type Session = {
  no: number;
  /** thứ trong tuần, ví dụ "T4" */
  day: string;
  /** khung giờ, ví dụ "17:45-19:15" */
  time: string;
  date: string;
  room: string;
  teacher: string;
  ta: string | null;
  /** đã làm báo cáo buổi chưa — null nếu buổi chưa diễn ra */
  report: boolean | null;
  attendance: boolean | null;
  /** đã giao bài sau buổi chưa */
  homework: boolean | null;
  past: boolean;
};

export type Assignment = {
  id: string;
  title: string;
  /** thuộc buổi số mấy */
  session: number;
  assigned: string;
  due: string;
  total: number;
  submitted: number;
  graded: number;
  avg: number | null;
};

